import java.util.Scanner;
import java.util.regex.*;
​
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String pattern = scanner.nextLine().toLowerCase();
        String input = scanner.nextLine().toLowerCase();

        // 构造正则表达式
        StringBuilder regex = new StringBuilder("^");
        boolean starSeen = false;
        for (char c : pattern.toCharArray()) {
            if (c == '*') {
                if (!starSeen) {
                    regex.append("[0-9a-z]{0,}");
                    starSeen = true;
                }
            } else if (c == '?') {
                regex.append("[0-9a-z]{1}");
                starSeen = false;
            } else {
                regex.append(Pattern.quote(Character.toString(c)));
                starSeen = false;
            }
        }
        regex.append("$");
​
        // 利用正则表达式匹配
        if (input.matches(regex.toString())) {
            System.out.println("true"); // 匹配成功输出true
        } else {
            System.out.println("false"); // 匹配失败输出false
        }
    }
}
