const readline = require('readline');
​
// 读取控制台输入
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
let lines = [];
rl.on('line', (line) => {
    lines.push(line.toLowerCase());
    if (lines.length === 2) {
        const pattern = lines[0];
        const input = lines[1];
​
        // 构造正则表达式
        let regex = "^";
        let starSeen = false;
        for (let c of pattern) {
            if (c === '*') {
                if (!starSeen) {
                    regex += "[0-9a-z]{0,}";
                    starSeen = true;
                }
            } else if (c === '?') {
                regex += "[0-9a-z]{1}";
                starSeen = false;
            } else {
                regex += c.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&'); // 转义特殊字符
                starSeen = false;
            }
        }
        regex += "$";
​
        const re = new RegExp(regex, 'i');
        if (re.test(input)) {
            console.log("true");  // 匹配成功输出true
        } else {
            console.log("false"); // 匹配失败输出false
        }
​
        rl.close();
    }
});
