package main
​
import (
    "bufio"
    "fmt"
    "os"
    "regexp"
    "strings"
)
​
func escapeRegexChar(c rune) string {
    special := "\\.^$|()[]{}*+?"
    if strings.ContainsRune(special, c) {
        return "\\" + string(c)
    }
    return string(c)
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    pattern, _ := reader.ReadString('\n')
    input, _ := reader.ReadString('\n')
​
    // 去除换行符并转换为小写
    pattern = strings.TrimSpace(strings.ToLower(pattern))
    input = strings.TrimSpace(strings.ToLower(input))
​
    // 构造正则表达式
    regex := "^"
    starSeen := false
    for _, c := range pattern {
        if c == '*' {
            if !starSeen {
                regex += "[0-9a-z]{0,}"
                starSeen = true
            }
        } else if c == '?' {
            regex += "[0-9a-z]{1}"
            starSeen = false
        } else {
            regex += escapeRegexChar(c)
            starSeen = false
        }
    }
    regex += "$"
​
    // 匹配正则
    re := regexp.MustCompile("(?i)" + regex)
    if re.MatchString(input) {
        fmt.Println("true")  // 匹配成功输出true
    } else {
        fmt.Println("false") // 匹配失败输出false
    }
}
